using CB701_KleberCustAddressIntegrationHelper;

/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// The class <c>METABNValidation</c> contains logic to validate ABN.
/// </summary>
class METKleberValidateCustAddressAddressHelper
{
    CustTable                   custTable;
    METATOWebServiceHelper      atoWebServiceHelper;
    AddressCountryRegionId      countryRegionId;
    TransDate                   todayDate;
    FormDataSource              callerDataSource;
    FormDataSource              dirPartyPostalAddressView_ds;



}

